Yes, you can modify it.

I also replaced my default files from [here](https://www.nushell.sh/book/configuration.html#nushell-configuration-with-env-nu-and-config-nu)

You can use my **init.nu**, you just have to modify your *starship binary path*.  Or just add a || to the **PROMPT_COMMAND** and **PROMPT_COMMAND_RIGHT**

```
let-env STARSHIP_SHELL = "nu"
let-env STARSHIP_SESSION_KEY = (random chars -l 16)
let-env PROMPT_MULTILINE_INDICATOR = (^'C:\Users\<user>\scoop\shims\starship.exe' prompt --continuation)

# Does not play well with default character module.
# TODO: Also Use starship vi mode indicators?
let-env PROMPT_INDICATOR = ""

let-env PROMPT_COMMAND = { ||
    # jobs are not supported
    let width = (term size).columns
    ^'C:\Users\<user>\scoop\shims\starship.exe' prompt $"--cmd-duration=($env.CMD_DURATION_MS)" $"--status=($env.LAST_EXIT_CODE)" $"--terminal-width=($width)"
}

# Whether we have config items
let has_config_items = (not ($env | get -i config | is-empty))

let-env config = if $has_config_items { 
    $env.config | upsert render_right_prompt_on_last_line true
} else { 
    {render_right_prompt_on_last_line: true}
}

let-env PROMPT_COMMAND_RIGHT = { ||
    let width = (term size).columns
    ^'C:\Users\<user>\scoop\shims\starship.exe' prompt --right $"--cmd-duration=($env.CMD_DURATION_MS)" $"--status=($env.LAST_EXIT_CODE)" $"--terminal-width=($width)"
}
```

If you're using nix you can also use an overlay to grab a revision of `starship` that has the fix. Here's one for the latest passing build:

```nix
    starship = prev.starship.overrideAttrs (oldAttrs: rec {
      src = pkgs.fetchFromGitHub {
        owner = "starship";
        repo = "starship";
        rev = "07d9bb1691cf42c354a4feb3affd977b97e5b937";
        sha256 = "sha256-jDvtUwPtBuQOXvecE8jPSIT2hsov6DybpeTjk3dH6Bc=";
      };
      cargoDeps = oldAttrs.cargoDeps.overrideAttrs (prev.lib.const {
        inherit src;
        name = "starship-07d9bb1691cf42c354a4feb3affd977b97e5b937-vendor.tar.gz";
        outputHash = "sha256-jf+lb9rZTjdqRLpC+hN8M/+DgNMCoLCmb4CyqjYbvtM=";
      });
    });

```

Pretty handy because the `nix` + `nushell` + `starship` combo can be pretty unstable.

As an alternative, you can also [patch](https://github.com/participant5/nixos-config/blob/e05b16124853ded2ab45f8b320e79f50b8e5b781/nixos/nix.nix#L12-L21) the existing release in Nix:

```nix
      starship = super.starship.overrideDerivation (oa: {
        patches = (oa.patches or [ ]) ++ [
          (builtins.fetchurl {
            name = "nushell.patch";
            url = "https://github.com/starship/starship/commit/041a51835371d3738cc7b597b4a506a5dc4341c9.diff";
            sha256 = "sha256:0az1jjb24mngzybgv7kavdj1bhfdm0cqnci3gz6zkgpaxqvw7vnz";
          })
        ];
      })
```
